import SwiftUI

/// The magic front door: tell Athen what just happened in your life, get a
/// concrete civic + benefits + action plan back. Generated by Claude with the
/// user's profile as context. Plans persist locally; the user can browse
/// past plans in `LifeEventHistoryView`.
struct LifeEventComposerView: View {
    @Environment(CivicOSStore.self) private var store
    @Environment(\.dismiss) private var dismiss

    /// Optional pre-fill from a Home tile or quick-action chip.
    let prefilledDescription: String?

    @State private var draft: String = ""
    @State private var generatedPlan: CivicLifeEventPlan?
    @State private var inlineError: String?
    @FocusState private var inputFocused: Bool

    init(prefilledDescription: String? = nil) {
        self.prefilledDescription = prefilledDescription
    }

    private static let suggestedPrompts: [String] = [
        "I just got laid off",
        "I had a baby",
        "I'm moving to a new state",
        "I just bought a house",
        "I'm starting a small business",
        "I lost my health insurance",
        "I'm getting divorced",
        "My parent moved in with me",
        "I just turned 65",
        "I got a notice from immigration",
        "I'm leaving the military",
        "I had a death in the family",
    ]

    var body: some View {
        NavigationStack {
            ZStack {
                CivicTheme.screenBackground.ignoresSafeArea()
                ScrollView(showsIndicators: false) {
                    VStack(alignment: .leading, spacing: 14) {
                        if let plan = generatedPlan {
                            planView(plan)
                        } else if store.isGeneratingLifeEventPlan {
                            generatingState
                        } else {
                            intro
                            inputCard
                            if let inlineError {
                                errorCard(inlineError)
                            }
                            suggestedChips
                            recentPlans
                        }
                        Color.clear.frame(height: 36)
                    }
                    .padding(.horizontal, 18)
                    .padding(.top, 14)
                }
            }
            .navigationTitle(generatedPlan == nil ? "Tell Athen" : "Your plan")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    Button(generatedPlan == nil ? "Close" : "Done") { dismiss() }
                        .foregroundStyle(CivicTheme.cyan)
                }
                ToolbarItem(placement: .topBarTrailing) {
                    if generatedPlan != nil {
                        Button {
                            Haptics.selection()
                            generatedPlan = nil
                            draft = ""
                            inputFocused = true
                        } label: {
                            Label("New", systemImage: "plus.circle.fill")
                                .foregroundStyle(CivicTheme.violet)
                        }
                    }
                }
            }
            .onAppear {
                if let prefilled = prefilledDescription, draft.isEmpty {
                    draft = prefilled
                }
            }
        }
    }

    // MARK: - Composer states

    private var intro: some View {
        VStack(alignment: .leading, spacing: 6) {
            Label("LIFE EVENT", systemImage: "sparkles")
                .font(.system(size: 11, weight: .bold))
                .tracking(0.5)
                .foregroundStyle(CivicTheme.violet)
            Text("Tell me what's going on")
                .font(.system(size: 24, weight: .bold))
                .foregroundStyle(CivicTheme.ink)
            Text("Got laid off? New baby? Moving across the country? Tell Athen in your own words and we'll lay out the civic side: what to do this week, what programs to apply for, and what's worth pushing your reps on.")
                .font(.system(size: 14))
                .lineSpacing(4)
                .foregroundStyle(CivicTheme.mutedInk)
                .fixedSize(horizontal: false, vertical: true)
        }
    }

    private var inputCard: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("WHAT HAPPENED?")
                .font(.system(size: 10, weight: .bold))
                .tracking(0.5)
                .foregroundStyle(CivicTheme.quietInk)
            TextEditor(text: $draft)
                .scrollContentBackground(.hidden)
                .focused($inputFocused)
                .font(.system(size: 15))
                .frame(minHeight: 120)
                .padding(10)
                .background(CivicTheme.panel, in: RoundedRectangle(cornerRadius: 12))
                .overlay(RoundedRectangle(cornerRadius: 12).stroke(CivicTheme.hairline, lineWidth: 1))
            Button {
                submit()
            } label: {
                HStack(spacing: 8) {
                    Image(systemName: "sparkles")
                        .font(.system(size: 14, weight: .bold))
                    Text("Make my plan")
                        .font(.system(size: 14, weight: .bold))
                }
                .foregroundStyle(.white)
                .frame(maxWidth: .infinity, minHeight: 50)
                .background(canSubmit ? CivicTheme.violet : CivicTheme.violet.opacity(0.4), in: RoundedRectangle(cornerRadius: 12))
                .shadow(color: CivicTheme.violet.opacity(0.25), radius: 8, x: 0, y: 3)
            }
            .buttonStyle(.plain)
            .disabled(!canSubmit)
        }
    }

    private var canSubmit: Bool {
        draft.trimmingCharacters(in: .whitespaces).count >= 4
    }

    private var suggestedChips: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("OR PICK A COMMON ONE")
                .font(.system(size: 10, weight: .bold))
                .tracking(0.5)
                .foregroundStyle(CivicTheme.quietInk)
            FlowLayout(spacing: 6) {
                ForEach(Self.suggestedPrompts, id: \.self) { prompt in
                    Button {
                        Haptics.selection()
                        draft = prompt
                        inputFocused = true
                    } label: {
                        Text(prompt)
                            .font(.system(size: 12, weight: .bold))
                            .foregroundStyle(CivicTheme.violet)
                            .padding(.horizontal, 10)
                            .padding(.vertical, 7)
                            .background(CivicTheme.violet.opacity(0.10), in: Capsule())
                            .overlay(Capsule().stroke(CivicTheme.violet.opacity(0.20), lineWidth: 1))
                    }
                    .buttonStyle(.plain)
                }
            }
        }
    }

    @ViewBuilder
    private var recentPlans: some View {
        if !store.lifeEventPlans.isEmpty {
            VStack(alignment: .leading, spacing: 8) {
                Text("YOUR RECENT PLANS")
                    .font(.system(size: 10, weight: .bold))
                    .tracking(0.5)
                    .foregroundStyle(CivicTheme.quietInk)
                ForEach(store.lifeEventPlans.prefix(3)) { plan in
                    Button {
                        Haptics.selection()
                        generatedPlan = plan
                    } label: {
                        recentPlanRow(plan)
                    }
                    .buttonStyle(.plain)
                }
            }
        }
    }

    private func recentPlanRow(_ plan: CivicLifeEventPlan) -> some View {
        HStack(spacing: 12) {
            Image(systemName: "doc.text.fill")
                .font(.system(size: 14, weight: .bold))
                .foregroundStyle(CivicTheme.violet)
                .frame(width: 36, height: 36)
                .background(CivicTheme.violet.opacity(0.10), in: RoundedRectangle(cornerRadius: 10))
            VStack(alignment: .leading, spacing: 3) {
                Text(plan.situation)
                    .font(.system(size: 13, weight: .bold))
                    .foregroundStyle(CivicTheme.ink)
                    .lineLimit(2)
                Text("\(plan.totalSteps) steps · \(relativeDate(plan.generatedAt))")
                    .font(.system(size: 11, weight: .medium))
                    .foregroundStyle(CivicTheme.mutedInk)
            }
            Spacer()
            Image(systemName: "chevron.right")
                .font(.system(size: 11, weight: .bold))
                .foregroundStyle(CivicTheme.quietInk)
        }
        .padding(10)
        .background(CivicTheme.panel, in: RoundedRectangle(cornerRadius: 12))
        .overlay(RoundedRectangle(cornerRadius: 12).stroke(CivicTheme.hairline, lineWidth: 1))
    }

    private var generatingState: some View {
        VStack(spacing: 18) {
            Spacer(minLength: 40)
            ZStack {
                Circle()
                    .fill(CivicTheme.violet.opacity(0.16))
                Image(systemName: "sparkles")
                    .font(.system(size: 32, weight: .bold))
                    .foregroundStyle(CivicTheme.violet)
            }
            .frame(width: 80, height: 80)
            VStack(spacing: 8) {
                Text("Building your plan")
                    .font(.system(size: 20, weight: .bold))
                    .foregroundStyle(CivicTheme.ink)
                Text("Athen is mapping your situation to programs, deadlines, and civic action. About 10 seconds.")
                    .font(.system(size: 13))
                    .multilineTextAlignment(.center)
                    .foregroundStyle(CivicTheme.mutedInk)
                    .padding(.horizontal, 24)
            }
            ProgressView().tint(CivicTheme.violet)
            Spacer(minLength: 0)
        }
        .frame(maxWidth: .infinity, minHeight: 400)
    }

    // MARK: - Plan rendering

    private func planView(_ plan: CivicLifeEventPlan) -> some View {
        VStack(alignment: .leading, spacing: 18) {
            planHeader(plan)
            if !plan.immediateSteps.isEmpty {
                stepsSection(title: "Do today", steps: plan.immediateSteps, tint: CivicTheme.red)
            }
            if !plan.nearTermSteps.isEmpty {
                stepsSection(title: "This week + month", steps: plan.nearTermSteps, tint: CivicTheme.amber)
            }
            if !plan.longerTermSteps.isEmpty {
                stepsSection(title: "Longer term", steps: plan.longerTermSteps, tint: CivicTheme.cyan)
            }
            if !plan.qualifyingPrograms.isEmpty {
                programsSection(plan.qualifyingPrograms)
            }
            if !plan.civicAsks.isEmpty {
                civicAsksSection(plan.civicAsks)
            }
            if !plan.notes.isEmpty {
                notesSection(plan.notes)
            }
            planActions(plan)
        }
    }

    private func planHeader(_ plan: CivicLifeEventPlan) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack(spacing: 6) {
                AIDisclosureChip(surface: .plan)
                Spacer()
                Text(plan.category.replacingOccurrences(of: "_", with: " ").uppercased())
                    .font(.system(size: 10, weight: .bold))
                    .tracking(0.4)
                    .foregroundStyle(CivicTheme.mutedInk)
            }
            Text(plan.situation)
                .font(.system(size: 22, weight: .bold))
                .foregroundStyle(CivicTheme.ink)
                .fixedSize(horizontal: false, vertical: true)
            Text("\(plan.totalSteps) actions · \(plan.qualifyingPrograms.count) program\(plan.qualifyingPrograms.count == 1 ? "" : "s") · generated \(relativeDate(plan.generatedAt))")
                .font(.system(size: 12, weight: .medium))
                .foregroundStyle(CivicTheme.quietInk)
            HStack {
                ReadAloudButton(text: { planReadAloudScript(plan) }, label: "Read plan")
                Spacer()
            }
            .padding(.top, 4)
        }
    }

    private func planReadAloudScript(_ plan: CivicLifeEventPlan) -> String {
        var parts: [String] = ["Your civic plan. \(plan.situation)."]
        if !plan.immediateSteps.isEmpty {
            parts.append("Do today.")
            parts.append(plan.immediateSteps.prefix(5).map { $0.title }.joined(separator: ". "))
        }
        if !plan.nearTermSteps.isEmpty {
            parts.append("This week and month.")
            parts.append(plan.nearTermSteps.prefix(5).map { $0.title }.joined(separator: ". "))
        }
        if !plan.longerTermSteps.isEmpty {
            parts.append("Longer term.")
            parts.append(plan.longerTermSteps.prefix(5).map { $0.title }.joined(separator: ". "))
        }
        if !plan.qualifyingPrograms.isEmpty {
            parts.append("Programs you may qualify for.")
            parts.append(plan.qualifyingPrograms.prefix(5).map { $0.name }.joined(separator: ". "))
        }
        return parts.joined(separator: " ")
    }

    private func stepsSection(title: String, steps: [PlanStep], tint: Color) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            sectionLabel(title, systemImage: "checklist", tint: tint)
            VStack(spacing: 8) {
                ForEach(steps) { step in
                    stepCard(step, tint: tint)
                }
            }
        }
    }

    private func stepCard(_ step: PlanStep, tint: Color) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                Text(step.urgency.label.uppercased())
                    .font(.system(size: 9, weight: .bold))
                    .tracking(0.4)
                    .foregroundStyle(.white)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background(step.urgency.tint, in: Capsule())
                Spacer()
            }
            Text(step.title)
                .font(.system(size: 15, weight: .bold))
                .foregroundStyle(CivicTheme.ink)
                .fixedSize(horizontal: false, vertical: true)
            Text(step.description)
                .font(.system(size: 13))
                .lineSpacing(3)
                .foregroundStyle(CivicTheme.mutedInk)
                .fixedSize(horizontal: false, vertical: true)
            stepActionButton(step)
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(CivicTheme.panel, in: RoundedRectangle(cornerRadius: 12))
        .overlay(RoundedRectangle(cornerRadius: 12).stroke(tint.opacity(0.20), lineWidth: 1))
    }

    @ViewBuilder
    private func stepActionButton(_ step: PlanStep) -> some View {
        let kind = step.action.kind
        if let url = step.action.url, let resolved = URL(string: url), [.url, .fileIssue, .service, .petition].contains(kind) {
            Link(destination: resolved) {
                actionChip(label: step.action.label ?? kind.label, systemImage: kind.systemImage)
            }
        } else if let phone = step.action.phone, kind == .phone {
            if let url = URL(string: "tel://\(phone.replacingOccurrences(of: " ", with: ""))") {
                Link(destination: url) {
                    actionChip(label: phone, systemImage: kind.systemImage)
                }
            } else {
                actionChip(label: phone, systemImage: kind.systemImage)
            }
        } else if kind == .calendar, let title = step.action.calendarTitle, let dateISO = step.action.calendarDateISO,
                  let url = calendarShortcutURL(title: title, dateISO: dateISO) {
            Link(destination: url) {
                actionChip(label: step.action.label ?? "Add to calendar", systemImage: kind.systemImage)
            }
        } else {
            actionChip(label: step.action.label ?? kind.label, systemImage: kind.systemImage, disabled: true)
        }
    }

    private func actionChip(label: String, systemImage: String, disabled: Bool = false) -> some View {
        HStack(spacing: 6) {
            Image(systemName: systemImage)
                .font(.system(size: 11, weight: .bold))
            Text(label)
                .font(.system(size: 12, weight: .bold))
                .lineLimit(1)
        }
        .foregroundStyle(disabled ? CivicTheme.quietInk : .white)
        .padding(.horizontal, 12)
        .padding(.vertical, 8)
        .background(disabled ? CivicTheme.panelElevated : CivicTheme.violet, in: Capsule())
    }

    /// Builds an iOS Calendar URL using webcal://. Best effort — for richer
    /// integration use the Composio Calendar action.
    private func calendarShortcutURL(title: String, dateISO: String) -> URL? {
        // Apple Calendar handles `calshow:` to open the app at a date, but
        // creating events via URL scheme is unreliable. Fallback: an x-callback
        // URL to Calendar.app's compose UI via Shortcuts is finicky. Cleanest
        // path is to surface the date as a "Set reminder" prompt the user
        // confirms in-app.
        var components = URLComponents()
        components.scheme = "calshow"
        components.path = dateISO
        return components.url
    }

    private func programsSection(_ programs: [QualifyingProgram]) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            sectionLabel("Programs you may qualify for", systemImage: "heart.text.square.fill", tint: CivicTheme.green)
            VStack(spacing: 8) {
                ForEach(programs) { program in
                    programCard(program)
                }
            }
        }
    }

    private func programCard(_ program: QualifyingProgram) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            Text(program.name)
                .font(.system(size: 15, weight: .bold))
                .foregroundStyle(CivicTheme.ink)
            Text(program.agency)
                .font(.system(size: 11, weight: .semibold))
                .foregroundStyle(CivicTheme.green)
            VStack(alignment: .leading, spacing: 6) {
                programRow(label: "ELIGIBILITY", value: program.eligibility)
                programRow(label: "BENEFITS", value: program.benefits)
                if let notes = program.notes {
                    programRow(label: "NOTE", value: notes)
                }
            }
            .padding(.top, 4)
            if let urlString = program.applyURL, let url = URL(string: urlString) {
                Link(destination: url) {
                    actionChip(label: "Apply", systemImage: "arrow.up.right.square")
                        .padding(.top, 4)
                }
            }
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(CivicTheme.green.opacity(0.05), in: RoundedRectangle(cornerRadius: 12))
        .overlay(RoundedRectangle(cornerRadius: 12).stroke(CivicTheme.green.opacity(0.20), lineWidth: 1))
    }

    private func programRow(label: String, value: String) -> some View {
        VStack(alignment: .leading, spacing: 2) {
            Text(label)
                .font(.system(size: 9, weight: .bold))
                .tracking(0.5)
                .foregroundStyle(CivicTheme.quietInk)
            Text(value)
                .font(.system(size: 12))
                .lineSpacing(2)
                .foregroundStyle(CivicTheme.ink)
                .fixedSize(horizontal: false, vertical: true)
        }
    }

    private func civicAsksSection(_ asks: [CivicAsk]) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            sectionLabel("Civic asks", systemImage: "person.3.sequence.fill", tint: CivicTheme.violet)
            VStack(spacing: 8) {
                ForEach(asks) { ask in
                    civicAskCard(ask)
                }
            }
        }
    }

    private func civicAskCard(_ ask: CivicAsk) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack {
                Text(ask.scope.label.uppercased())
                    .font(.system(size: 9, weight: .bold))
                    .tracking(0.4)
                    .foregroundStyle(.white)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background(ask.scope.tint, in: Capsule())
                Spacer()
            }
            Text(ask.title)
                .font(.system(size: 14, weight: .bold))
                .foregroundStyle(CivicTheme.ink)
                .fixedSize(horizontal: false, vertical: true)
            Text(ask.description)
                .font(.system(size: 12))
                .lineSpacing(3)
                .foregroundStyle(CivicTheme.mutedInk)
                .fixedSize(horizontal: false, vertical: true)
            if !ask.why.isEmpty {
                Text("Why: \(ask.why)")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(CivicTheme.violet)
                    .padding(.top, 2)
            }
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(ask.scope.tint.opacity(0.06), in: RoundedRectangle(cornerRadius: 12))
        .overlay(RoundedRectangle(cornerRadius: 12).stroke(ask.scope.tint.opacity(0.20), lineWidth: 1))
    }

    private func notesSection(_ notes: [String]) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            sectionLabel("Notes", systemImage: "info.circle.fill", tint: CivicTheme.cyan)
            ForEach(notes, id: \.self) { note in
                HStack(alignment: .top, spacing: 6) {
                    Circle().fill(CivicTheme.cyan).frame(width: 4, height: 4).padding(.top, 7)
                    Text(note)
                        .font(.system(size: 12))
                        .lineSpacing(3)
                        .foregroundStyle(CivicTheme.mutedInk)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
        }
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(CivicTheme.cyan.opacity(0.05), in: RoundedRectangle(cornerRadius: 12))
    }

    private func planActions(_ plan: CivicLifeEventPlan) -> some View {
        HStack(spacing: 10) {
            ShareLink(item: shareText(plan)) {
                HStack(spacing: 6) {
                    Image(systemName: "square.and.arrow.up")
                    Text("Share")
                }
                .font(.system(size: 13, weight: .bold))
                .foregroundStyle(CivicTheme.cyan)
                .frame(maxWidth: .infinity, minHeight: 42)
                .background(CivicTheme.cyan.opacity(0.10), in: RoundedRectangle(cornerRadius: 10))
            }
            .simultaneousGesture(TapGesture().onEnded { Haptics.selection() })
            Button(role: .destructive) {
                Haptics.selection()
                store.deleteLifeEventPlan(plan.id)
                dismiss()
            } label: {
                HStack(spacing: 6) {
                    Image(systemName: "trash")
                    Text("Delete plan")
                }
                .font(.system(size: 13, weight: .bold))
                .foregroundStyle(CivicTheme.red)
                .frame(maxWidth: .infinity, minHeight: 42)
                .background(CivicTheme.red.opacity(0.10), in: RoundedRectangle(cornerRadius: 10))
            }
            .buttonStyle(.plain)
        }
    }

    // MARK: - Submit + helpers

    private func submit() {
        guard canSubmit else { return }
        Haptics.impact(.medium)
        inlineError = nil
        Task {
            do {
                let plan = try await store.generateLifeEventPlan(description: draft.trimmingCharacters(in: .whitespacesAndNewlines))
                Haptics.success()
                generatedPlan = plan
            } catch {
                Haptics.error()
                inlineError = (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
            }
        }
    }

    private func errorCard(_ message: String) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Image(systemName: "exclamationmark.triangle.fill")
                .foregroundStyle(CivicTheme.red)
            Text(message)
                .font(.system(size: 12, weight: .semibold))
                .foregroundStyle(CivicTheme.mutedInk)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(10)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(CivicTheme.red.opacity(0.08), in: RoundedRectangle(cornerRadius: 10))
    }

    private func sectionLabel(_ title: String, systemImage: String, tint: Color) -> some View {
        HStack(spacing: 6) {
            Image(systemName: systemImage)
                .font(.system(size: 11, weight: .bold))
                .foregroundStyle(tint)
            Text(title.uppercased())
                .font(.system(size: 10, weight: .bold))
                .tracking(0.5)
                .foregroundStyle(tint)
            Rectangle()
                .fill(tint.opacity(0.25))
                .frame(height: 1)
        }
    }

    private func relativeDate(_ date: Date) -> String {
        let elapsed = -date.timeIntervalSinceNow
        switch elapsed {
        case ..<60: return "just now"
        case ..<3600: return "\(max(1, Int(elapsed / 60)))m ago"
        case ..<86400: return "\(max(1, Int(elapsed / 3600)))h ago"
        default: return "\(max(1, Int(elapsed / 86400)))d ago"
        }
    }

    private func shareText(_ plan: CivicLifeEventPlan) -> String {
        var lines: [String] = []
        lines.append("My Athen plan: \(plan.situation)")
        lines.append("")
        if !plan.immediateSteps.isEmpty {
            lines.append("DO TODAY:")
            for step in plan.immediateSteps {
                lines.append("• \(step.title) — \(step.description)")
            }
            lines.append("")
        }
        if !plan.qualifyingPrograms.isEmpty {
            lines.append("PROGRAMS TO LOOK INTO:")
            for prog in plan.qualifyingPrograms {
                lines.append("• \(prog.name) — \(prog.eligibility)")
            }
            lines.append("")
        }
        lines.append("Generated by Athen.")
        return lines.joined(separator: "\n")
    }
}
